import re
import os
import glob
from pathlib import Path

def task_func(pattern, directory, extensions):
    try:
        regex = re.compile(pattern, re.IGNORECASE)
    except (TypeError, re.error):
        return []

    base_dir = Path(directory).expanduser()
    if not base_dir.is_dir():
        return []

    if extensions is None:
        normalized_extensions = None
    elif isinstance(extensions, str):
        normalized_extensions = {extensions.lower() if extensions.startswith(".") else f".{extensions.lower()}"}
    else:
        normalized_extensions = {
            ext.lower() if str(ext).startswith(".") else f".{str(ext).lower()}"
            for ext in extensions
        }

    matched_files = []

    for file_path in base_dir.rglob("*"):
        if not file_path.is_file():
            continue

        if normalized_extensions is not None and file_path.suffix.lower() not in normalized_extensions:
            continue

        try:
            with file_path.open("r", encoding="utf-8", errors="ignore") as file:
                if regex.search(file.read()):
                    matched_files.append(str(file_path.resolve()))
        except (OSError, UnicodeError):
            continue

    return matched_files

